# ============================================================================
# Fincept Terminal - Strategy Engine Option Chains (model-priced)
#
# Historical option listings and quotes are not available from any free source,
# so chains are generated by rule from the real underlying price:
#   * listed_expiries(): OCC/CBOE-style expiry calendars (monthlies, weeklies,
#     Mon-Thu dailies, end-of-month/quarter, LEAPS, VIX Wednesdays, futures
#     options), each listed only within a horizon before it expires;
#   * strike_ladder(): strikes on a fixed global grid (so a contract keeps the
#     same Symbol day after day) in a band around the price known at the chain
#     date that widens with time to expiry;
#   * option_chain_symbols(): the contract Symbols of one canonical option;
#   * LEAN-shaped data classes (Greeks, OptionContract, OptionChain,
#     OptionChains) and LEAN's OptionFilterUniverse with its semantics.
# Prices come from a caller-supplied quote callback (see option_model.py); this
# module never reads market data itself.
# ============================================================================

import bisect
import math
from datetime import date, datetime, timedelta
from typing import NamedTuple

from . import market_calendar as cal
from .enums import OptionRight, SecurityType
from .errors import not_supported
from .types import Symbol, SymbolDict, DEFAULT_DATE, future_option_root

_OPTION_TYPES = (SecurityType.OPTION, SecurityType.INDEX_OPTION, SecurityType.FUTURE_OPTION)
_CALL = OptionRight.CALL
_PUT = OptionRight.PUT

# ---------------------------------------------------------------------------
# Expiry calendars
# ---------------------------------------------------------------------------

KIND_MONTHLY = 'monthly'            # standard 3rd-Friday expiry (equity, or AM-settled index monthly)
KIND_MONTHLY_PM = 'monthly_pm'      # PM-settled 3rd-Friday expiry of a weekly index root (SPXW, RUTW, ...)
KIND_LEAPS = 'leaps'                # a standard expiry listed only because of the long-dated (LEAPS) horizon
KIND_WEEKLY = 'weekly'              # Friday (Thursday when Friday is a holiday) non-monthly expiry
KIND_DAILY = 'daily'                # Monday-Thursday expiry
KIND_MONTH_END = 'month_end'        # last trading day of the month
KIND_QUARTER_END = 'quarter_end'    # last trading day of Mar/Jun/Sep/Dec
KIND_VIX_MONTHLY = 'vix_monthly'    # VIX: Wednesday 30 days before the next month's 3rd Friday
KIND_VIX_WEEKLY = 'vix_weekly'      # VIXW: other Wednesdays
KIND_FUTURE_OPTION = 'future_option'

STANDARD_KINDS = frozenset({KIND_MONTHLY, KIND_LEAPS, KIND_VIX_MONTHLY, KIND_FUTURE_OPTION})

# Days before expiry from which a contract is listed (approximations of the exchanges' listing rules).
LISTING_HORIZON_DAYS = {
    KIND_DAILY: 21,
    KIND_WEEKLY: 42,
    KIND_MONTH_END: 92,
    KIND_QUARTER_END: 366,
    'monthly_near': 93,       # single stocks: every month for ~3 months ...
    'monthly_cycle': 366,     # ... and the Mar/Jun/Sep/Dec months for a year
    'monthly_all': 366,       # broad ETFs and indexes: every month for a year
    'index_quarterly': 731,   # AM-settled index roots: Mar/Jun/Sep/Dec for two years
    KIND_LEAPS: 913,          # January (and December for ETFs/indexes) out to ~2.5 years
    KIND_VIX_MONTHLY: 250,
    KIND_VIX_WEEKLY: 42,
    KIND_FUTURE_OPTION: 731,
}

# Approximate first listing dates of the non-standard expiry programs. Before a program's start date
# its expiries are not generated. These dates are approximations (documented, not exchange-verified).
EXPIRY_PROGRAMS = {
    'SPXW': {'friday': date(2005, 10, 28), 'quarter_end': date(2006, 7, 3), 'month_end': date(2014, 7, 1),
             'third_friday_pm': date(2016, 1, 1), 'wednesday': date(2016, 2, 23), 'monday': date(2016, 8, 15),
             'tuesday': date(2022, 4, 18), 'thursday': date(2022, 5, 11)},
    'SPY': {'friday': date(2010, 6, 4), 'quarter_end': date(2008, 1, 2), 'wednesday': date(2016, 3, 1),
            'monday': date(2016, 8, 15), 'tuesday': date(2022, 11, 14), 'thursday': date(2022, 11, 14)},
    'QQQ': {'friday': date(2010, 6, 4), 'quarter_end': date(2008, 1, 2), 'wednesday': date(2018, 11, 5),
            'monday': date(2018, 11, 5), 'tuesday': date(2022, 11, 14), 'thursday': date(2022, 11, 14)},
    'IWM': {'friday': date(2010, 6, 4), 'quarter_end': date(2008, 1, 2), 'wednesday': date(2018, 11, 5),
            'monday': date(2018, 11, 5)},
    'RUTW': {'friday': date(2010, 6, 4), 'third_friday_pm': date(2016, 1, 1), 'month_end': date(2016, 1, 1)},
    'NDXP': {'friday': date(2018, 1, 2), 'third_friday_pm': date(2018, 1, 2)},
    'NQX': {'friday': date(2021, 1, 25), 'third_friday_pm': date(2021, 1, 25)},
    'XSP': {'friday': date(2012, 1, 3), 'third_friday_pm': date(2005, 1, 3), 'month_end': date(2016, 1, 4)},
    'VIXW': {'wednesday': date(2015, 10, 21)},
}
# Single stocks and other ETFs: Friday weeklies from this date. In reality only several hundred liquid
# names have weeklies; generating them for every equity is a disclosed approximation.
DEFAULT_EQUITY_PROGRAMS = {'friday': date(2011, 1, 3)}

# ETFs listed with every monthly for a year plus December/January LEAPS.
BROAD_ETFS = frozenset({
    'SPY', 'QQQ', 'IWM', 'DIA', 'GLD', 'SLV', 'TLT', 'IEF', 'HYG', 'LQD', 'EEM', 'EFA', 'FXI', 'EWZ', 'GDX',
    'GDXJ', 'USO', 'UNG', 'XLF', 'XLE', 'XLK', 'XLU', 'XLV', 'XLI', 'XLP', 'XLY', 'XLB', 'XLC', 'XLRE', 'SMH',
    'XBI', 'KRE', 'XOP', 'ARKK', 'VXX', 'UVXY', 'SQQQ', 'TQQQ', 'IBB', 'XRT', 'MDY', 'VTI', 'VOO', 'IVV'})

# Index roots that list AM-settled standard monthlies (settlement value at the expiry morning's open).
AM_MONTHLY_INDEX_ROOTS = frozenset({'SPX', 'NDX', 'RUT', 'DJX', 'OEX', 'XEO'})
AM_SETTLED_ROOTS = frozenset({'SPX', 'NDX', 'RUT', 'DJX', 'VIX', 'VIXW'})
# LEAN IndexOptionSymbol: these roots have weeklies and monthlies; standard = expiring on the 3rd Friday.
_INDEX_ROOTS_WITH_WEEKLIES = frozenset({'NQX', 'SPXW', 'RUTW'})
# Future roots whose quarterly options settle to the opening quotation (SOQ), like their futures.
_AM_SETTLED_FUTURE_ROOTS = frozenset({'ES', 'NQ', 'YM', 'RTY', 'EMD', 'MES', 'MNQ', 'MYM', 'M2K'})

_OCC_FRIDAY_SWITCH = date(2015, 2, 1)   # equity standard monthlies were dated on Saturday before Feb 2015


class ListedExpiry(NamedTuple):
    date: datetime              # the contract expiry (Symbol.id.date), at 00:00
    kind: str                   # KIND_*
    settlement: str             # 'AM' (opening settlement on `date`) or 'PM'
    last_trading_date: date

    @property
    def is_standard(self) -> bool:
        return self.kind in STANDARD_KINDS


def _as_date(x) -> date:
    if isinstance(x, datetime):
        return x.date()
    if isinstance(x, date):
        return x
    raise TypeError(f"expected a date or datetime, got {type(x).__name__}")


def _dt(d: date) -> datetime:
    return datetime(d.year, d.month, d.day)


def _months_from(d0: date, count: int):
    y, m = d0.year, d0.month
    for _ in range(count):
        yield y, m
        m += 1
        if m == 13:
            y, m = y + 1, 1


def _trading_or_previous(d: date) -> date:
    return d if cal.is_trading_day(d) else cal.previous_trading_day(d)


def equity_monthly_expiry(year: int, month: int):
    """(expiry date, last trading date) of the standard equity option expiring in `month`: the 3rd Friday
    (the previous trading day when it is an NYSE holiday); dated on the following Saturday, as OCC did,
    for expirations before February 2015."""
    tf = cal.third_friday(year, month)
    if tf < _OCC_FRIDAY_SWITCH:
        return tf + timedelta(days=1), _trading_or_previous(tf)
    d = _trading_or_previous(tf)
    return d, d


def index_monthly_expiry(year: int, month: int) -> date:
    """3rd Friday of the month, or the previous trading day when it is an NYSE holiday."""
    return _trading_or_previous(cal.third_friday(year, month))


def vix_monthly_expiry(year: int, month: int) -> date:
    """VIX options/futures final settlement date in `month`: the Wednesday 30 days before the 3rd Friday of
    the following month (30 days before the trading day preceding that Friday if it is a holiday), moved to
    the previous trading day if that Wednesday is a holiday."""
    ny, nm = (year + 1, 1) if month == 12 else (year, month + 1)
    w = _trading_or_previous(cal.third_friday(ny, nm)) - timedelta(days=30)
    return _trading_or_previous(w)


def _add_business_days(d: date, n: int) -> date:
    return cal.add_trading_days(d, n)


def _future_contract_month(root: str, future_expiry: date):
    """Contract month of a future from its expiry date (energy futures expire the month before)."""
    shift = 1 if root in ('CL', 'NG', 'HO', 'RB', 'MCL', 'QM') else (2 if root == 'BZ' else 0)
    y, m = future_expiry.year, future_expiry.month + shift
    while m > 12:
        y, m = y + 1, m - 12
    return y, m


def _prev_month(y, m):
    return (y - 1, 12) if m == 1 else (y, m - 1)


def future_option_expiry(future_root: str, future_expiry) -> date:
    """Expiry of the standard (quarterly/serial) option on the future of `future_root` expiring on
    `future_expiry`, following LEAN's FuturesOptionsExpiryFunctions rules for the common roots (NYSE
    holidays are used as an approximation of the CME holiday calendar); other roots: the future's expiry."""
    root = str(future_root).upper()
    fx = _as_date(future_expiry)
    y, m = _future_contract_month(root, fx)
    py, pm = _prev_month(y, m)
    if root in ('CL', 'MCL'):
        # 7 business days before the 26th calendar day of the month prior to the contract month
        d26 = date(py, pm, 26)
        return _add_business_days(d26, -7)
    if root == 'NG':
        return cal.nth_last_business_day(py, pm, 4)
    if root in ('ZB', 'ZC', 'ZN', 'TN', 'UB', 'ZO', 'KE', 'ZF', 'ZS', 'ZT', 'ZW', 'ZL', 'ZM'):
        d = cal.nth_last_business_day(py, pm, 2) - timedelta(days=1)
        while d.weekday() != cal.FRIDAY or not cal.is_trading_day(d):
            d -= timedelta(days=1)
        return d
    if root in ('GC', 'SI', 'HG', 'MGC'):
        d = cal.nth_last_business_day(py, pm, 4)
        while d.weekday() == cal.FRIDAY or cal.is_holiday(d + timedelta(days=1)):
            d = cal.previous_trading_day(d)
        return d
    if root in ('6A', '6B', '6C', '6E', '6J', '6S', '6N', '6M'):
        d = cal.third_wednesday(y, m) - timedelta(days=12)
        return d if cal.is_trading_day(d) else cal.previous_trading_day(d)
    if root == 'LE':
        return _trading_or_previous(cal.nth_weekday(y, m, cal.FRIDAY, 1))
    if root == 'HE':
        return cal.nth_business_day(y, m, 10)
    if root in ('ES', 'EMD', 'YM', 'NQ', 'RTY', 'MES', 'MNQ', 'MYM', 'M2K'):
        return _trading_or_previous(cal.third_friday(y, m))
    return fx


def _programs(root: str, security_type) -> dict:
    p = EXPIRY_PROGRAMS.get(root)
    if p is not None:
        return p
    return DEFAULT_EQUITY_PROGRAMS if security_type == SecurityType.OPTION else {}


def listed_expiries(root: str, as_of, security_type=SecurityType.OPTION, underlying=None) -> list:
    """Expiries of option root `root` listed on the date of `as_of` (only expiries whose last trading date
    is on or after it), sorted, each a ListedExpiry. `underlying` (the future contract Symbol) is required
    for futures options."""
    d0 = _as_date(as_of)
    root = str(root).upper()
    if security_type == SecurityType.FUTURE_OPTION:
        return _future_option_expiries(underlying, d0)
    if security_type == SecurityType.INDEX_OPTION and root in ('VIX', 'VIXW'):
        return _vix_expiries(d0, weekly=(root == 'VIXW'))

    is_equity = security_type == SecurityType.OPTION
    progs = _programs(root, security_type)
    active = {name for name, start in progs.items() if d0 >= start}
    found = {}   # date -> ListedExpiry, standard ones first so they win on a shared date

    def add(exp: date, kind: str, settlement: str, ltd: date):
        if ltd < d0 or exp in found:
            return
        found[exp] = ListedExpiry(_dt(exp), kind, settlement, ltd)

    H = LISTING_HORIZON_DAYS
    broad = is_equity and root in BROAD_ETFS
    am_index = (not is_equity) and (root in AM_MONTHLY_INDEX_ROOTS or root not in EXPIRY_PROGRAMS)
    pm_monthly = (not is_equity) and not am_index and 'third_friday_pm' in active

    for y, m in _months_from(d0, 32):
        if is_equity:
            exp, ltd = equity_monthly_expiry(y, m)
            settlement = 'PM'
            if broad:
                regular = H['monthly_all']
                leaps_months = (1, 12)
            else:
                regular = H['monthly_cycle'] if m in (3, 6, 9, 12) else H['monthly_near']
                leaps_months = (1,)
        elif am_index:
            exp = index_monthly_expiry(y, m)
            ltd = cal.previous_trading_day(exp)
            settlement = 'AM'
            regular = H['index_quarterly'] if m in (3, 6, 9, 12) else H['monthly_all']
            leaps_months = (12,)
        elif pm_monthly:
            exp = index_monthly_expiry(y, m)
            ltd, settlement = exp, 'PM'
            regular = H['monthly_all']
            leaps_months = ()
        else:
            break
        days = (exp - d0).days
        if days <= regular:
            add(exp, KIND_MONTHLY if (is_equity or am_index) else KIND_MONTHLY_PM, settlement, ltd)
        elif days <= H[KIND_LEAPS] and m in leaps_months:
            add(exp, KIND_LEAPS, settlement, ltd)

    for y, m in _months_from(d0, 14):
        if m in (3, 6, 9, 12) and 'quarter_end' in active:
            e = cal.last_business_day(y, m)
            if (e - d0).days <= H[KIND_QUARTER_END]:
                add(e, KIND_QUARTER_END, 'PM', e)
    for y, m in _months_from(d0, 4):
        if 'month_end' in active:
            e = cal.last_business_day(y, m)
            if (e - d0).days <= H[KIND_MONTH_END]:
                add(e, KIND_MONTH_END, 'PM', e)

    if 'friday' in active:
        f = d0 + timedelta(days=(cal.FRIDAY - d0.weekday()) % 7)
        end = d0 + timedelta(days=H[KIND_WEEKLY])
        while f <= end:
            if f != cal.third_friday(f.year, f.month):
                e = _trading_or_previous(f)
                add(e, KIND_WEEKLY, 'PM', e)
            f += timedelta(days=7)

    daily = [wd for wd, name in ((cal.MONDAY, 'monday'), (cal.TUESDAY, 'tuesday'),
                                 (cal.WEDNESDAY, 'wednesday'), (cal.THURSDAY, 'thursday')) if name in active]
    if daily:
        x, end = d0, d0 + timedelta(days=H[KIND_DAILY])
        while x <= end:
            if x.weekday() in daily and cal.is_trading_day(x):
                add(x, KIND_DAILY, 'PM', x)
            x += timedelta(days=1)

    return sorted(found.values(), key=lambda e: e.date)


def _vix_expiries(d0: date, weekly: bool) -> list:
    monthly = [vix_monthly_expiry(y, m) for y, m in _months_from(d0, 12)]
    monthly_set = set(monthly)
    out = []
    if not weekly:
        for e in monthly:
            ltd = cal.previous_trading_day(e)
            if ltd >= d0 and (e - d0).days <= LISTING_HORIZON_DAYS[KIND_VIX_MONTHLY]:
                out.append(ListedExpiry(_dt(e), KIND_VIX_MONTHLY, 'AM', ltd))
        return out
    start = EXPIRY_PROGRAMS['VIXW']['wednesday']
    if d0 < start:
        return out
    w = d0 + timedelta(days=(cal.WEDNESDAY - d0.weekday()) % 7)
    end = d0 + timedelta(days=LISTING_HORIZON_DAYS[KIND_VIX_WEEKLY])
    while w <= end:
        if cal.is_trading_day(w) and w not in monthly_set:
            ltd = cal.previous_trading_day(w)
            if ltd >= d0:
                out.append(ListedExpiry(_dt(w), KIND_VIX_WEEKLY, 'AM', ltd))
        w += timedelta(days=7)
    return out


def _future_option_expiries(underlying, d0: date) -> list:
    if underlying is None or getattr(underlying, 'security_type', None) != SecurityType.FUTURE:
        raise ValueError("listed_expiries: futures options need the underlying future contract Symbol")
    fx = underlying.id.date
    if fx is None or fx == DEFAULT_DATE:
        raise ValueError(f"listed_expiries: {underlying} is a canonical future; futures options are listed per "
                         f"future contract (pass the contract Symbol)")
    root = underlying.id.symbol
    out = []
    for e in _future_option_expiry_list(root, fx):
        if e < d0 or (e - d0).days > LISTING_HORIZON_DAYS[KIND_FUTURE_OPTION]:
            continue
        am = root in _AM_SETTLED_FUTURE_ROOTS and e == index_monthly_expiry(e.year, e.month) and e.month % 3 == 0
        ltd = cal.previous_trading_day(e) if am else e
        if ltd < d0:
            continue
        out.append(ListedExpiry(_dt(e), KIND_FUTURE_OPTION, 'AM' if am else 'PM', ltd))
    return out


# Metals list options every month; a serial month's options exercise into the next listed futures
# contract (CME: e.g. gold March options -> April futures). Futures contract months per root:
_SERIAL_OPTION_CYCLES = {'GC': (2, 4, 6, 8, 10, 12), 'MGC': (2, 4, 6, 8, 10, 12),
                         'SI': (3, 5, 7, 9, 12), 'HG': (3, 5, 7, 9, 12)}


def _future_option_expiry_list(root: str, future_expiry) -> list:
    """Expiries of the options on one futures contract: the standard one, plus for metals the serial
    months whose options exercise into this contract (the months after the previous futures month)."""
    fx = _as_date(future_expiry)
    cycle = _SERIAL_OPTION_CYCLES.get(str(root).upper())
    if not cycle:
        return [future_option_expiry(root, fx)]
    y, m = _future_contract_month(root, fx)
    prev = max([c for c in cycle if c < m], default=None)
    py = y if prev is not None else y - 1
    prev = prev if prev is not None else cycle[-1]
    months = []
    oy, om = py, prev
    while (oy, om) != (y, m):
        om += 1
        if om > 12:
            oy, om = oy + 1, 1
        months.append((oy, om))
    return sorted({future_option_expiry(root, date(oy, om, 20)) for oy, om in months})


# ---------------------------------------------------------------------------
# Per-contract expiry facts (LEAN OptionSymbol / IndexOptionSymbol semantics)
# ---------------------------------------------------------------------------

def is_standard(symbol) -> bool:
    """LEAN's OptionSymbol.IsStandard / IndexOptionSymbol.IsStandard / FutureOptionSymbol.IsStandard."""
    st = symbol.security_type
    d = symbol.id.date
    if st == SecurityType.FUTURE_OPTION:
        return True
    if st == SecurityType.INDEX_OPTION:
        if str(symbol.id.market).lower() != 'usa':
            return True
        if symbol.id.symbol in _INDEX_ROOTS_WITH_WEEKLIES:
            return cal.third_friday(d.year, d.month) == d.date()
        return True
    first_friday = 1 + (cal.FRIDAY - date(d.year, d.month, 1).weekday()) % 7
    # the week containing the 3rd Friday, Thursday to Saturday (Mon/Wed/Fri weeklies excluded)
    return first_friday + 12 < d.day < first_friday + 16


def is_weekly(symbol) -> bool:
    """LEAN OptionSymbol.IsWeekly: not standard and expiring on a Friday."""
    return not is_standard(symbol) and symbol.id.date.weekday() == cal.FRIDAY


_LTD_CACHE = {}


def _lean_last_trading_date(symbol) -> date:
    """The last trading date LEAN's filters use: equity options walk back from the expiry to the previous
    open day (Saturday-dated standard contracts before 2015 to the Friday); other options use the expiry."""
    d = symbol.id.date
    if symbol.security_type != SecurityType.OPTION:
        return d.date()
    key = d
    r = _LTD_CACHE.get(key)
    if r is None:
        x = d.date()
        if d.weekday() == cal.SATURDAY and x < _OCC_FRIDAY_SWITCH and is_standard(symbol):
            x -= timedelta(days=1)
        while not cal.is_trading_day(x):
            x -= timedelta(days=1)
        if len(_LTD_CACHE) > 20000:
            _LTD_CACHE.clear()
        _LTD_CACHE[key] = r = x
    return r


def settlement_type(symbol) -> str:
    """'AM' (settles at the open of the expiry date) or 'PM' (at the close of the last trading day)."""
    st = symbol.security_type
    if st == SecurityType.INDEX_OPTION:
        root = symbol.id.symbol
        if root in AM_SETTLED_ROOTS:
            return 'AM'
        return 'PM'
    if st == SecurityType.FUTURE_OPTION:
        u = symbol.underlying
        root = u.id.symbol if u is not None else ''
        d = symbol.id.date.date()
        if root in _AM_SETTLED_FUTURE_ROOTS and d.month % 3 == 0 and d == index_monthly_expiry(d.year, d.month):
            return 'AM'
        return 'PM'
    return 'PM'


def last_trading_date(symbol) -> date:
    """The contract's last trading date: the trading day before the expiry for AM-settled contracts,
    otherwise the expiry (walked back to an open day; pre-2015 Saturday-dated equity contracts: Friday)."""
    if settlement_type(symbol) == 'AM':
        return cal.previous_trading_day(symbol.id.date.date())
    if symbol.security_type == SecurityType.OPTION:
        return _lean_last_trading_date(symbol)
    return _trading_or_previous(symbol.id.date.date())


_EXPIRY_DT_CACHE = {}


def expiry_datetime(symbol) -> datetime:
    """When the contract stops having time value, used for time to expiry: 09:30 of the expiry date for
    AM-settled contracts, otherwise the regular close of the last trading date (13:00 on early closes)."""
    r = _EXPIRY_DT_CACHE.get(symbol)
    if r is not None:
        return r
    d = symbol.id.date
    if settlement_type(symbol) == 'AM':
        r = datetime(d.year, d.month, d.day, 9, 30)
    else:
        ltd = last_trading_date(symbol)
        r = datetime.combine(ltd, cal.market_close_time(ltd) or cal.MARKET_CLOSE)
    if len(_EXPIRY_DT_CACHE) > 200000:
        _EXPIRY_DT_CACHE.clear()
    _EXPIRY_DT_CACHE[symbol] = r
    return r


def _listed_expiry_datetime(e: ListedExpiry) -> datetime:
    if e.settlement == 'AM':
        return datetime.combine(e.date.date(), cal.MARKET_OPEN)
    return datetime.combine(e.last_trading_date, cal.market_close_time(e.last_trading_date) or cal.MARKET_CLOSE)


def time_to_expiry(symbol, t: datetime) -> float:
    """Years (calendar days / 365, LEAN's convention) from t to expiry_datetime(symbol); 0 when past."""
    secs = (expiry_datetime(symbol) - t).total_seconds()
    return secs / 31536000.0 if secs > 0 else 0.0


# ---------------------------------------------------------------------------
# Strike grids
# ---------------------------------------------------------------------------
# Tiers: ((upper bound of the strike level or None, increment), ...), ascending. Every tier boundary is a
# multiple of the increments on both sides, so the grid is the same whatever the underlying price is.

EQUITY_STRIKE_TIERS = ((10.0, 0.5), (50.0, 1.0), (150.0, 2.5), (1000.0, 5.0), (None, 10.0))
ETF_STRIKE_TIERS = ((25.0, 0.5), (None, 1.0))
INDEX_STRIKE_TIERS = {
    'SPX': ((None, 5.0),), 'SPXW': ((None, 5.0),), 'XSP': ((None, 1.0),), 'OEX': ((None, 5.0),),
    'XEO': ((None, 5.0),), 'NDX': ((5000.0, 10.0), (None, 25.0)), 'NDXP': ((5000.0, 10.0), (None, 25.0)),
    'NQX': ((None, 5.0),), 'RUT': ((None, 5.0),), 'RUTW': ((None, 5.0),), 'DJX': ((None, 1.0),),
    'VIX': ((20.0, 0.5), (50.0, 1.0), (None, 2.5)), 'VIXW': ((20.0, 0.5), (50.0, 1.0), (None, 2.5)),
}
# Futures options, keyed by the FUTURE root.
FUTURE_STRIKE_TIERS = {
    'ES': ((None, 5.0),), 'MES': ((None, 5.0),), 'EMD': ((None, 5.0),), 'NQ': ((None, 25.0),),
    'MNQ': ((None, 25.0),), 'YM': ((None, 100.0),), 'MYM': ((None, 100.0),), 'RTY': ((None, 10.0),),
    'M2K': ((None, 10.0),), 'GC': ((None, 5.0),), 'MGC': ((None, 5.0),), 'SI': ((None, 0.25),),
    'HG': ((None, 0.05),), 'CL': ((None, 0.5),), 'MCL': ((None, 0.5),), 'NG': ((None, 0.05),),
    'ZB': ((None, 1.0),), 'UB': ((None, 1.0),), 'ZN': ((None, 0.5),), 'ZF': ((None, 0.25),),
    'ZT': ((None, 0.125),), 'ZC': ((None, 5.0),), 'ZS': ((None, 10.0),), 'ZW': ((None, 5.0),),
    'KE': ((None, 5.0),), 'ZL': ((None, 0.5),), 'ZM': ((None, 5.0),), 'ZO': ((None, 5.0),),
    '6E': ((None, 0.005),), '6B': ((None, 0.005),), '6A': ((None, 0.005),), '6C': ((None, 0.005),),
    '6S': ((None, 0.005),), 'LE': ((None, 1.0),), 'HE': ((None, 1.0),),
}
_MIN_INCREMENT_MILLI = 1   # OSI tickers carry the strike in thousandths


def _generic_tiers(lo: float, hi: float) -> tuple:
    """A level-based grid with ~0.4-1% spacing: in [1, 2.5)x10^n steps of 10^(n-2), [2.5, 5)x10^n steps of
    2.5x10^(n-2), [5, 10)x10^n steps of 5x10^(n-2)."""
    n0 = int(math.floor(math.log10(max(lo, 1e-3))))
    n1 = int(math.floor(math.log10(max(hi, 1e-3)))) + 1
    tiers = []
    for n in range(n0, n1 + 1):
        b = 10.0 ** n
        mid = 2.5 * b / 100.0
        if abs(mid * 1000 - round(mid * 1000)) > 1e-9:
            mid = 2.0 * b / 100.0     # 2.5e-3 is not representable in OSI thousandths; 2e-3 divides both bounds
        tiers += [(2.5 * b, b / 100.0), (5.0 * b, mid), (10.0 * b, 5.0 * b / 100.0)]
    tiers[-1] = (None, tiers[-1][1])
    return tuple(tiers)


def strike_tiers(root: str, security_type, underlying=None):
    """The strike-increment tiers of an option root; None means the generic level-based grid."""
    root = str(root).upper()
    if security_type == SecurityType.INDEX_OPTION:
        return INDEX_STRIKE_TIERS.get(root)
    if security_type == SecurityType.FUTURE_OPTION:
        froot = underlying.id.symbol if underlying is not None else root
        return FUTURE_STRIKE_TIERS.get(froot)
    return ETF_STRIKE_TIERS if root in BROAD_ETFS else EQUITY_STRIKE_TIERS


def _tiers_milli(tiers):
    out = []
    for bound, inc in tiers:
        im = int(round(inc * 1000))
        if im < _MIN_INCREMENT_MILLI or abs(inc * 1000 - im) > 1e-6:
            raise not_supported("option strikes finer than 0.001",
                                "OSI option tickers carry strikes in thousandths; this product's strike "
                                "increment is smaller, so its chain cannot be generated.")
        out.append((None if bound is None else int(round(bound * 1000)), im))
    return out


def _inc_at(k: int, tiers_m) -> int:
    for bound, inc in tiers_m:
        if bound is None or k < bound:
            return inc
    return tiers_m[-1][1]


def _nice(x: int) -> bool:
    while x % 10 == 0:
        x //= 10
    return x in (1, 25, 5)


def _coarse_inc(inc: int) -> int:
    c = inc * 5
    return c if _nice(c) else inc * 4


def strike_increment(level: float, tiers=None) -> float:
    """The grid increment at strike `level` for the given tiers (None: generic grid)."""
    t = tiers if tiers is not None else _generic_tiers(level, level)
    return _inc_at(int(round(level * 1000)), _tiers_milli(t)) / 1000.0


def _band_width(price, T, sigma, min_band, n_sigma, max_band) -> float:
    return price * min(max_band, max(min_band, n_sigma * max(sigma, 0.0) * math.sqrt(max(T, 0.0))))


def _grid_points(lo_m: int, hi_m: int, tiers_m) -> list:
    """Grid points (thousandths) in [lo_m, hi_m]; one range() per tier segment."""
    pts = []
    seg_lo = 0
    for bound, inc in tiers_m:
        # tier covers [seg_lo, bound); seg_lo is a multiple of inc (tier boundaries are)
        seg_hi = hi_m if bound is None else min(hi_m, bound - 1)
        start = max(lo_m, seg_lo, 1)
        start = -(-start // inc) * inc
        if start <= seg_hi:
            pts.extend(range(start, seg_hi + 1, inc))
        if bound is None or bound > hi_m:
            break
        seg_lo = bound
    return pts


def _ladder_milli(price: float, width: float, tiers, dense_strikes: int, coarse_strikes: int) -> list:
    lo, hi = max(price - width, 0.0), price + width
    tiers_m = _tiers_milli(tiers if tiers is not None else _generic_tiers(max(lo, price * 0.05), hi))
    pts = _grid_points(int(math.ceil(lo * 1000 - 1e-6)), int(math.floor(hi * 1000 + 1e-6)), tiers_m)
    if not pts:
        return []
    p_m = price * 1000.0
    i = bisect.bisect_left(pts, p_m)
    if i >= len(pts) or (i > 0 and p_m - pts[i - 1] <= pts[i] - p_m):
        i -= 1
    a, b = max(0, i - dense_strikes), min(len(pts), i + dense_strikes + 1)
    keep = pts[a:b]
    n = 0
    for k in reversed(pts[:a]):
        if n >= coarse_strikes:
            break
        if k % _coarse_inc(_inc_at(k, tiers_m)) == 0:
            keep.append(k)
            n += 1
    n = 0
    for k in pts[b:]:
        if n >= coarse_strikes:
            break
        if k % _coarse_inc(_inc_at(k, tiers_m)) == 0:
            keep.append(k)
            n += 1
    keep.sort()
    return keep


def strike_ladder(price: float, T: float, sigma: float, tiers=None, *, min_band: float = 0.15,
                  n_sigma: float = 4.0, max_band: float = 0.9, dense_strikes: int = 20,
                  coarse_strikes: int = 20) -> list:
    """Strikes listed around `price` for an expiry T years away: grid points within
    price * min(max_band, max(min_band, n_sigma*sigma*sqrt(T))) of the price; every grid point among the
    `dense_strikes` nearest the money on each side, beyond that only points on a 4-5x coarser increment,
    at most `coarse_strikes` more per side. Sorted floats. (A narrower band's ladder is exactly the wider
    band's ladder clipped to the narrower band, which option_chain_spec uses to build a day's chain once.)"""
    if not (price > 0):
        return []
    width = _band_width(price, T, sigma, min_band, n_sigma, max_band)
    return [k / 1000.0 for k in _ladder_milli(price, width, tiers, dense_strikes, coarse_strikes)]


# ---------------------------------------------------------------------------
# Contract symbols
# ---------------------------------------------------------------------------

_SYMBOL_CACHE = {}
_SYMBOL_CACHE_MAX = 500000


def contract_symbol(canonical, right, strike: float, expiry, underlying=None):
    """The contract Symbol of `canonical` (keeps its target option name, e.g. SPXW, its market and style).
    Cached, so the same contract is the same Symbol object every day."""
    u = underlying if underlying is not None else canonical.underlying
    if u is None:
        raise ValueError(f"contract_symbol: {canonical} has no underlying symbol")
    exp = expiry if isinstance(expiry, datetime) else _dt(_as_date(expiry))
    exp = datetime(exp.year, exp.month, exp.day)
    strike = round(float(strike), 6)
    key = (canonical.value, u.value, exp, int(right), strike)
    s = _SYMBOL_CACHE.get(key)
    if s is not None:
        return s
    st = canonical.security_type
    target = canonical.id.symbol
    default = future_option_root(u.id.symbol) if st == SecurityType.FUTURE_OPTION else u.id.symbol
    market = canonical.id.market
    style = canonical.id.option_style
    r = OptionRight(int(right))
    if target != default:
        s = Symbol.create_option(u, target, market, style, r, strike, exp)
    else:
        s = Symbol.create_option(u, market, style, r, strike, exp)
    if len(_SYMBOL_CACHE) >= _SYMBOL_CACHE_MAX:
        _SYMBOL_CACHE.clear()
    _SYMBOL_CACHE[key] = s
    return s


class ChainConfig:
    """Strike band / density parameters of generated chains (see strike_ladder)."""

    def __init__(self, min_band=0.15, n_sigma=4.0, max_band=0.9, dense_strikes=20, coarse_strikes=20):
        self.min_band = min_band
        self.n_sigma = n_sigma
        self.max_band = max_band
        self.dense_strikes = dense_strikes
        self.coarse_strikes = coarse_strikes


DEFAULT_CHAIN_CONFIG = ChainConfig()


def default_vol_hint(security_type, root: str) -> float:
    root = str(root).upper()
    if root in ('VIX', 'VIXW'):
        return 1.0
    if security_type == SecurityType.INDEX_OPTION:
        return 0.25
    if security_type == SecurityType.FUTURE_OPTION:
        return 0.30
    return 0.35


def option_chain_spec(canonical, underlying_symbol, as_of: datetime, underlying_price: float,
                      vol_hint: float = None, config: ChainConfig = None) -> list:
    """[(ListedExpiry, [strike, ...]), ...] listed for `canonical` at `as_of`, using only `underlying_price`
    (the price known at as_of) and `vol_hint` (annualised at-the-money volatility; widens the band)."""
    if canonical is None or canonical.security_type not in _OPTION_TYPES:
        raise ValueError(f"option_chain_spec: {canonical} is not an option symbol")
    if not isinstance(as_of, datetime):
        raise TypeError("option_chain_spec: as_of must be a datetime")
    cfg = config or DEFAULT_CHAIN_CONFIG
    u = underlying_symbol if underlying_symbol is not None else canonical.underlying
    if not (underlying_price and underlying_price > 0):
        return []
    return [(e, [k / 1000.0 for k in ks]) for e, ks in _spec_milli(canonical, u, as_of, float(underlying_price),
                                                                     vol_hint, cfg)]


def _spec_milli(canonical, u, as_of, price, vol_hint, cfg):
    root = canonical.id.symbol
    st = canonical.security_type
    sigma = vol_hint if (vol_hint is not None and vol_hint > 0) else default_vol_hint(st, root)
    tiers = strike_tiers(root, st, u)
    expiries = listed_expiries(root, as_of, st, u)
    if not expiries:
        return []
    widths = []
    for e in expiries:
        secs = (_listed_expiry_datetime(e) - as_of).total_seconds()
        T = secs / 31536000.0 if secs > 0 else 0.0
        widths.append(_band_width(price, T, sigma, cfg.min_band, cfg.n_sigma, cfg.max_band))
    # one ladder for the widest band; each expiry takes the part inside its own band (identical to
    # strike_ladder() for that expiry, see its docstring)
    full = _ladder_milli(price, max(widths), tiers, cfg.dense_strikes, cfg.coarse_strikes)
    out = []
    for e, w in zip(expiries, widths):
        lo = bisect.bisect_left(full, int(math.ceil(max(price - w, 0.0) * 1000 - 1e-6)))
        hi = bisect.bisect_right(full, int(math.floor((price + w) * 1000 + 1e-6)))
        out.append((e, full[lo:hi]))
    return out


_EXPIRY_SYMBOLS = {}     # (canonical, underlying, expiry) -> {strike in thousandths: (call, put)}


def option_chain_symbols(canonical, underlying_symbol, as_of: datetime, underlying_price: float,
                         vol_hint: float = None, config: ChainConfig = None) -> list:
    """Contract Symbols (calls and puts) of `canonical` listed at `as_of`; sorted by expiry, strike, right.
    Deterministic: depends only on the arguments (no look-ahead possible)."""
    if canonical is None or canonical.security_type not in _OPTION_TYPES:
        raise ValueError(f"option_chain_symbols: {canonical} is not an option symbol")
    if not isinstance(as_of, datetime):
        raise TypeError("option_chain_symbols: as_of must be a datetime")
    if not (underlying_price and underlying_price > 0):
        return []
    u = underlying_symbol if underlying_symbol is not None else canonical.underlying
    cfg = config or DEFAULT_CHAIN_CONFIG
    out = []
    for e, strikes_m in _spec_milli(canonical, u, as_of, float(underlying_price), vol_hint, cfg):
        key = (canonical.value, u.value, e.date)
        pairs = _EXPIRY_SYMBOLS.get(key)
        if pairs is None:
            if len(_EXPIRY_SYMBOLS) > 5000:
                _EXPIRY_SYMBOLS.clear()
            pairs = _EXPIRY_SYMBOLS[key] = {}
        for km in strikes_m:
            pair = pairs.get(km)
            if pair is None:
                k = km / 1000.0
                pair = pairs[km] = (contract_symbol(canonical, _CALL, k, e.date, u),
                                    contract_symbol(canonical, _PUT, k, e.date, u))
            out.extend(pair)
    return out


def chain_disclosure(config: ChainConfig = None) -> str:
    cfg = config or DEFAULT_CHAIN_CONFIG
    H = LISTING_HORIZON_DAYS
    return (
        "Option chains are generated by rule, not read from historical listings: standard expiries on the "
        "3rd Friday (previous trading day on an NYSE holiday; equity options dated the following Saturday "
        "before February 2015), Friday weeklies (all equities from 2011, approximate), Monday-Thursday, "
        "end-of-month and end-of-quarter expiries for SPXW/SPY/QQQ/IWM from approximate program start "
        "dates, January (and December for broad ETFs and indexes) LEAPS, VIX expiries on the Wednesday 30 "
        "days before the next month's 3rd Friday, one futures-option expiry per future contract (gold, silver and copper also carry the serial "
        "months that exercise into that contract; LEAN's rules, NYSE holidays). An expiry is listed only from a fixed horizon before it: Mon-Thu "
        f"{H[KIND_DAILY]} days, weeklies {H[KIND_WEEKLY]}, month-ends {H[KIND_MONTH_END]}, monthlies "
        f"{H['monthly_near']}-{H['monthly_all']} (index quarterlies {H['index_quarterly']}), LEAPS "
        f"{H[KIND_LEAPS]}. Strikes lie on a fixed grid whose increment depends on the product and strike level, "
        f"within max({cfg.min_band:.0%}, {cfg.n_sigma:g} x volatility x sqrt(T)) of the underlying price known "
        f"at the chain date (capped at {cfg.max_band:.0%}), every grid strike for the {cfg.dense_strikes} "
        f"strikes nearest the money on each side and a 4-5x coarser increment beyond (at most "
        f"{cfg.dense_strikes + cfg.coarse_strikes} strikes per side). Open interest and volume are not "
        "available from any free source and are reported as 0.")


CHAIN_DISCLOSURE = chain_disclosure()


# ---------------------------------------------------------------------------
# LEAN-shaped data classes
# ---------------------------------------------------------------------------

def _pascal(name: str) -> str:
    return ''.join(w[:1].upper() + w[1:] for w in name.split('_'))


def _alias(cls, names, extra=None):
    """PascalCase aliases (LEAN's C# names) of methods/properties; instance attributes get a property."""
    def target(n):
        if n in cls.__dict__:
            return cls.__dict__[n]
        return property(lambda self, _n=n: getattr(self, _n))

    for n in names:
        p = _pascal(n)
        if p not in cls.__dict__:
            setattr(cls, p, target(n))
    for p, n in (extra or {}).items():
        setattr(cls, p, target(n))


class Greeks:
    """LEAN Greeks: delta, gamma, vega (per vol point), theta (per year), rho (per rate point), lambda_
    and theta_per_day. Built eagerly from values or lazily from compute() -> (delta, gamma, vega, theta,
    rho, lambda) on first access."""

    __slots__ = ('_compute', '_v')

    def __init__(self, delta=0.0, gamma=0.0, vega=0.0, theta=0.0, rho=0.0, lambda_=0.0, compute=None):
        self._compute = compute
        self._v = None if compute is not None else (float(delta), float(gamma), float(vega), float(theta),
                                                     float(rho), float(lambda_))

    @classmethod
    def lazy(cls, compute):
        return cls(compute=compute)

    def _vals(self):
        v = self._v
        if v is None:
            v = self._v = tuple(float(x) for x in self._compute())
            self._compute = None
        return v

    delta = property(lambda self: self._vals()[0])
    gamma = property(lambda self: self._vals()[1])
    vega = property(lambda self: self._vals()[2])
    theta = property(lambda self: self._vals()[3])
    rho = property(lambda self: self._vals()[4])
    lambda_ = property(lambda self: self._vals()[5])
    theta_per_day = property(lambda self: self._vals()[3] / 365.0)

    def __repr__(self):
        d, g, v, t, r, _ = self._vals()
        return f"D: {d:.6g}, G: {g:.6g}, V: {v:.6g}, T: {t:.6g}, R: {r:.6g}"

    __str__ = __repr__


_alias(Greeks, ['delta', 'gamma', 'vega', 'theta', 'rho', 'theta_per_day'], {'Lambda': 'lambda_',
                                                                            'Lambda_': 'lambda_'})


class OptionQuote:
    """One model quote of an option contract at a moment (see option_model.OptionModel.quote)."""

    __slots__ = ('symbol', 'time', 'at', 'mid', 'bid', 'ask', 'implied_volatility', 'greeks',
                 'underlying_price', 'forward', 'time_to_expiry', 'rate', 'dividend_yield', 'model',
                 'atm_volatility')

    def __init__(self, symbol, time, mid, bid, ask, implied_volatility, greeks, underlying_price,
                 at='close', forward=None, time_to_expiry=None, rate=None, dividend_yield=None, model=None,
                 atm_volatility=None):
        self.symbol = symbol
        self.time = time
        self.at = at
        self.mid = mid
        self.bid = bid
        self.ask = ask
        self.implied_volatility = implied_volatility
        self.greeks = greeks
        self.underlying_price = underlying_price
        self.forward = forward
        self.time_to_expiry = time_to_expiry
        self.rate = rate
        self.dividend_yield = dividend_yield
        self.model = model
        self.atm_volatility = atm_volatility

    @property
    def theoretical_price(self):
        return self.mid

    price = theoretical_price

    def __repr__(self):
        iv = self.implied_volatility
        return (f"OptionQuote({self.symbol}, bid={self.bid:.4f}, mid={self.mid:.4f}, ask={self.ask:.4f}, "
                f"iv={'n/a' if iv is None else format(iv, '.4f')})")


class ChainUnderlying:
    """The underlying data point of a chain / filter universe: .price, .close, .value, .symbol, .time."""

    __slots__ = ('symbol', 'price', 'time', 'end_time')

    def __init__(self, symbol, price, time=None):
        self.symbol = symbol
        self.price = float(price)
        self.time = time
        self.end_time = time

    close = property(lambda self: self.price)
    value = property(lambda self: self.price)
    Symbol = property(lambda self: self.symbol)
    Price = property(lambda self: self.price)
    Close = property(lambda self: self.price)
    Value = property(lambda self: self.price)
    Time = property(lambda self: self.time)
    EndTime = property(lambda self: self.end_time)

    def __repr__(self):
        return f"ChainUnderlying({self.symbol}, {self.price})"


def as_underlying(underlying, symbol=None, time=None):
    """A ChainUnderlying from a number, an object with .price (TradeBar, Security, ...) or None."""
    if underlying is None:
        return None
    if isinstance(underlying, ChainUnderlying):
        return underlying
    if isinstance(underlying, (int, float)):
        return ChainUnderlying(symbol, underlying, time)
    price = getattr(underlying, 'price', None)
    if price is None:
        price = getattr(underlying, 'close', None)
    return ChainUnderlying(getattr(underlying, 'symbol', symbol) or symbol, float(price or 0.0),
                           getattr(underlying, 'end_time', None) or getattr(underlying, 'time', None) or time)


class OptionContract:
    """LEAN OptionContract over a model quote. The quote is computed on first access of a price, greek or
    implied volatility (quote_fn(symbol) -> OptionQuote), once. Open interest and volume are 0 (not
    available from any free source); last_price is the model mid."""

    __slots__ = ('symbol', 'time', '_underlying', '_quote', '_quote_fn', '_model_error')

    def __init__(self, symbol, time=None, underlying=None, quote=None, quote_fn=None):
        self.symbol = symbol
        self.time = time
        self._underlying = underlying
        self._quote = quote
        self._quote_fn = quote_fn
        self._model_error = None     # set when the security's price model does not support the style

    def _model_q(self):
        err = self._model_error
        if err is not None:
            raise err
        return self._q()

    def _q(self):
        q = self._quote
        if q is None:
            fn = self._quote_fn
            if fn is None:
                raise not_supported(f"model prices for option contract {self.symbol}",
                                    "No option pricing callback was supplied for this chain.")
            q = self._quote = fn(self.symbol)
        return q

    @property
    def quote(self):
        return self._q()

    # identity
    id = property(lambda self: self.symbol.id)
    underlying_symbol = property(lambda self: self.symbol.underlying)
    strike = property(lambda self: self.symbol.id.strike_price)
    scaled_strike = strike
    right = property(lambda self: self.symbol.id.option_right)
    style = property(lambda self: self.symbol.id.option_style)
    expiry = property(lambda self: self.symbol.id.date)
    underlying = property(lambda self: self._underlying)

    @property
    def days_to_expiry(self) -> int:
        t = self.time
        if t is None:
            return 0
        return (_lean_last_trading_date(self.symbol) - _as_date(t)).days

    # model prices
    bid_price = property(lambda self: self._q().bid)
    ask_price = property(lambda self: self._q().ask)
    last_price = property(lambda self: self._q().mid)
    price = last_price
    value = last_price
    close = last_price
    theoretical_price = property(lambda self: self._model_q().mid)
    implied_volatility = property(lambda self: self._model_q().implied_volatility)
    greeks = property(lambda self: self._model_q().greeks)

    @property
    def underlying_last_price(self):
        q = self._quote
        if q is not None and q.underlying_price is not None:
            return q.underlying_price
        u = self._underlying
        if u is not None:
            return u.price
        return self._q().underlying_price

    # not available: reported as 0 (disclosed in CHAIN_DISCLOSURE)
    volume = property(lambda self: 0)
    open_interest = property(lambda self: 0.0)
    bid_size = property(lambda self: 0)
    ask_size = property(lambda self: 0)

    def __str__(self):
        return self.symbol.value

    def __repr__(self):
        return f"OptionContract({self.symbol.value})"


_alias(OptionContract, ['symbol', 'time', 'underlying_symbol', 'strike', 'scaled_strike', 'right', 'style',
                        'expiry', 'days_to_expiry', 'bid_price', 'ask_price', 'last_price', 'price', 'value',
                        'close', 'theoretical_price', 'implied_volatility', 'greeks', 'underlying_last_price',
                        'volume', 'open_interest', 'bid_size', 'ask_size', 'underlying'], {'ID': 'id'})


class _Enumerator:
    """C# IEnumerator: move_next() / current."""

    def __init__(self, items):
        self._it = iter(items)
        self.current = None

    def move_next(self):
        try:
            self.current = next(self._it)
            return True
        except StopIteration:
            self.current = None
            return False

    MoveNext = move_next
    Current = property(lambda self: self.current)


class OptionContracts(SymbolDict):
    """Contracts of a chain keyed by Symbol (ticker strings accepted)."""
    pass


def _to_symbol_list(items):
    out = []
    for x in items:
        if isinstance(x, Symbol):
            out.append(x)
        elif isinstance(x, OptionContract):
            out.append(x.symbol)
        elif isinstance(x, str):
            out.append(x)
        else:
            s = getattr(x, 'symbol', None)
            if s is None:
                raise TypeError(f"expected Symbols or option contracts, got {type(x).__name__}")
            out.append(s)
    return out


_DF_COLUMNS = ('underlyingsymbol', 'expiry', 'strike', 'scaledstrike', 'right', 'style', 'openinterest',
               'lastprice', 'volume', 'bidprice', 'bidsize', 'askprice', 'asksize', 'theoreticalprice',
               'impliedvolatility', 'delta', 'gamma', 'vega', 'theta', 'rho', 'underlyinglastprice')


def _contract_row(c: OptionContract):
    g = c.greeks
    return (c.symbol.underlying, c.expiry, c.strike, c.scaled_strike, c.right, c.style, c.open_interest,
            c.last_price, c.volume, c.bid_price, c.bid_size, c.ask_price, c.ask_size, c.theoretical_price,
            c.implied_volatility, g.delta, g.gamma, g.vega, g.theta, g.rho, c.underlying_last_price)


class OptionChain:
    """LEAN OptionChain: the contracts of one canonical option at a time, iterable in (expiry, strike, right)
    order, with .contracts (keyed by Symbol), .underlying (.price/.close/.value/.symbol), .symbol (the
    canonical), .time, len(), .data_frame, and LEAN's chain filters (strikes, calls_only, straddle, ...),
    each returning a new OptionChain."""

    def __init__(self, symbol, time, contracts=(), underlying=None, quote_fn=None, flatten=True):
        self.symbol = symbol
        self.time = time
        self.end_time = time
        self._quote_fn = quote_fn
        self._flatten = flatten
        self.underlying = as_underlying(underlying, symbol.underlying if symbol is not None else None, time)
        if isinstance(contracts, OptionFilterUniverse):
            contracts = contracts.data
        items = []
        tday = _as_date(time) if time is not None else None
        for c in contracts:
            if not isinstance(c, OptionContract):
                sym = c if isinstance(c, Symbol) else getattr(c, 'symbol', c)
                c = OptionContract(sym, time, self.underlying, quote_fn=quote_fn)
            if tday is not None and c.symbol.id.date.date() < tday:
                continue
            items.append(c)
        items.sort(key=lambda c: (c.symbol.id.date, c.symbol.id.strike_price, int(c.symbol.id.option_right)))
        self.contracts = OptionContracts((c.symbol, c) for c in items)
        self.filtered_contracts = set(self.contracts.keys())
        self._df = None

    def __iter__(self):
        return iter(list(self.contracts.values()))

    def __len__(self):
        return len(self.contracts)

    def __contains__(self, key):
        return key in self.contracts

    def __getitem__(self, key):
        return self.contracts[key]

    @property
    def count(self):
        return len(self.contracts)

    def contains_key(self, key) -> bool:
        return key in self.contracts

    def get(self, key, default=None):
        return self.contracts.get(key, default)

    def __repr__(self):
        return f"OptionChain({self.symbol}, {self.time}, {len(self.contracts)} contracts)"

    @property
    def data_frame(self):
        """pandas DataFrame indexed by contract Symbol (index name 'symbol'), LEAN's flattened columns."""
        if self._df is None:
            import pandas as pd
            rows = [_contract_row(c) for c in self.contracts.values()]
            idx = pd.Index([c.symbol for c in self.contracts.values()], name='symbol', dtype=object)
            self._df = pd.DataFrame(rows, index=idx, columns=list(_DF_COLUMNS))
        return self._df

    # ---- filters (LEAN OptionChain.Filters) ----
    def _universe(self):
        return OptionFilterUniverse(list(self.contracts.values()), self.underlying, self.time,
                                    quote_fn=self._quote_fn,
                                    security_type=self.symbol.security_type if self.symbol is not None else None)

    def _derive(self, universe):
        return OptionChain(self.symbol, self.time, universe.data, self.underlying, self._quote_fn, self._flatten)

    def filter(self, func):
        """New chain with the contracts selected by func(OptionFilterUniverse)."""
        u = self._universe()
        return self._derive(apply_filter(func, u))

    def where(self, predicate):
        return self._derive(self._universe().where(predicate))


_CHAIN_FILTER_METHODS = (
    'strikes', 'strikes_above', 'strikes_below', 'calls_only', 'puts_only', 'out_of_the_money', 'otm',
    'in_the_money', 'itm', 'at_the_money', 'atm', 'delta', 'd', 'gamma', 'g', 'theta', 't', 'vega', 'v', 'rho',
    'r', 'implied_volatility', 'iv', 'naked_call', 'naked_put', 'call_spread', 'put_spread',
    'call_calendar_spread', 'put_calendar_spread', 'strangle', 'straddle', 'protective_collar', 'conversion',
    'call_butterfly', 'put_butterfly', 'iron_butterfly', 'iron_condor', 'box_spread', 'jelly_roll',
    'call_ladder', 'put_ladder', 'expiration', 'expiring_after', 'expiring_before', 'zero_dte',
    'standards_only', 'weeklys_only', 'front_month', 'farthest_expiration', 'back_months', 'back_month',
    'open_interest', 'oi', 'volume')


def _make_chain_filter(name):
    def method(self, *args, **kwargs):
        u = self._universe()
        getattr(u, name)(*args, **kwargs)
        return self._derive(u.apply_types_filter())
    method.__name__ = name
    method.__doc__ = f"LEAN OptionChain.{_pascal(name)}: a new chain filtered like OptionFilterUniverse.{name}."
    return method


for _n in _CHAIN_FILTER_METHODS:
    setattr(OptionChain, _n, _make_chain_filter(_n))
_SHORT_FILTER_ALIASES = frozenset({'otm', 'itm', 'atm', 'd', 'g', 't', 'v', 'r', 'iv', 'oi', 'zero_dte'})
_alias(OptionChain, ['symbol', 'time', 'end_time', 'underlying', 'contracts', 'count', 'contains_key',
                     'data_frame', 'filtered_contracts', 'where', 'filter'] + [
    n for n in _CHAIN_FILTER_METHODS if n not in _SHORT_FILTER_ALIASES],
    {'OTM': 'otm', 'ITM': 'itm', 'ATM': 'atm', 'D': 'd', 'G': 'g', 'T': 't', 'V': 'v', 'R': 'r', 'IV': 'iv',
     'OI': 'oi', 'ZeroDte': 'zero_dte'})
del _n


class OptionChainKeyValuePair(tuple):
    """(key, value) pair yielded when iterating OptionChains, with .key/.value (and Key/Value)."""

    __slots__ = ()

    def __new__(cls, key, value):
        return tuple.__new__(cls, (key, value))

    key = property(lambda self: self[0])
    value = property(lambda self: self[1])
    Key = key
    Value = value


def _canonical_value_for(key) -> str:
    """The canonical-option ticker LEAN would map `key` to (an option, an underlying or a ticker string)."""
    if isinstance(key, Symbol):
        st = key.security_type
        if st in _OPTION_TYPES:
            if key.has_underlying:
                return key.canonical.value
            return key.value
        if st == SecurityType.FUTURE:
            return '?' + future_option_root(key.id.symbol)
        return '?' + key.id.symbol
    s = str(key).strip().upper()
    if s.startswith('?'):
        return s
    if len(s) >= 16 and s[-15:-9].isdigit() and s[-9] in 'CP' and s[-8:].isdigit():
        return '?' + s[:-15].strip()
    return '?' + s


class OptionChains(SymbolDict):
    """LEAN OptionChains: OptionChain per canonical option Symbol. Lookups accept the canonical, any of its
    contracts, the underlying Symbol (mapped to its default canonical, e.g. SPX -> ?SPX) or a ticker string;
    iteration yields (key, value) pairs with .key/.value like LEAN's KeyValuePair."""

    def __init__(self, time=None, flatten=True):
        super().__init__()
        self.time = time
        self._flatten = flatten
        self._df = None

    def _resolve(self, key):
        if key is None:
            return None
        if dict.__contains__(self, key if isinstance(key, Symbol) else str(key).upper()):
            return key if isinstance(key, Symbol) else str(key).upper()
        v = _canonical_value_for(key)
        return v if dict.__contains__(self, v) else None

    def add(self, chain, key=None):
        self[key if key is not None else chain.symbol] = chain

    def __setitem__(self, key, chain):
        k = key if isinstance(key, Symbol) else (getattr(chain, 'symbol', None) or str(key).upper())
        if isinstance(k, Symbol) and k.security_type in _OPTION_TYPES and k.has_underlying:
            k = k.canonical
        dict.__setitem__(self, k, chain)
        self._df = None

    def __getitem__(self, key):
        k = self._resolve(key)
        if k is None:
            raise KeyError(f"'{key}' wasn't found in the OptionChains object, likely because there was no-data "
                           f"at this moment in time and it wasn't possible to fillforward historical data.")
        return dict.__getitem__(self, k)

    def __contains__(self, key):
        return self._resolve(key) is not None

    def get(self, key, default=None):
        k = self._resolve(key)
        return dict.__getitem__(self, k) if k is not None else default

    def get_value(self, key):
        return self.get(key)

    def contains_key(self, key) -> bool:
        return self._resolve(key) is not None

    def try_get_value(self, key):
        v = self.get(key)
        return (v is not None, v)

    def __iter__(self):
        return iter([OptionChainKeyValuePair(k, v) for k, v in dict.items(self)])

    @property
    def data_frame(self):
        """pandas DataFrame with a ('canonical', 'symbol') MultiIndex over every chain's contracts."""
        if self._df is None:
            import pandas as pd
            rows, idx = [], []
            for canonical, chain in dict.items(self):
                for c in chain.contracts.values():
                    rows.append(_contract_row(c))
                    idx.append((canonical, c.symbol))
            mi = pd.MultiIndex.from_tuples(idx, names=['canonical', 'symbol']) if idx else \
                pd.MultiIndex.from_arrays([[], []], names=['canonical', 'symbol'])
            self._df = pd.DataFrame(rows, index=mi, columns=list(_DF_COLUMNS))
        return self._df

    GetValue = get_value
    ContainsKey = contains_key
    TryGetValue = try_get_value
    DataFrame = data_frame
    Get = get


# ---------------------------------------------------------------------------
# OptionFilterUniverse (LEAN semantics)
# ---------------------------------------------------------------------------

_STANDARD = 1
_WEEKLY = 2
_BOTH = _STANDARD | _WEEKLY
_MAX = float('inf')        # LEAN's decimal.MaxValue sentinel of GetClosestStrike
_MAX_DAYS = 36500


def _to_timedelta(x) -> timedelta:
    if isinstance(x, timedelta):
        return x
    if x is None:
        return timedelta(0)
    days = float(x)
    return timedelta(days=min(days, _MAX_DAYS)) if days >= 0 else timedelta(days=max(days, -_MAX_DAYS))


def _is_iterable(x) -> bool:
    if isinstance(x, (str, bytes)):
        return False
    try:
        iter(x)
        return True
    except TypeError:
        return False


def _k(x: float) -> float:
    return round(float(x), 6)


class OptionFilterUniverse:
    """LEAN's OptionFilterUniverse over a list of contracts (Symbols or OptionContracts).

    Methods filter in place and return self (chainable), with LEAN's semantics: strikes(min, max) counts
    unique strikes relative to the underlying price; expiration() compares last trading dates with the
    universe date (moved to the next trading day when it is not one); include_weeklys/weeklys_only/
    standards_only select by LEAN's IsStandard and are applied lazily (by front_month/back_months/
    farthest_expiration and by apply_types_filter(), which the caller runs after the user's filter);
    the strategy filters (straddle, iron_condor, ...) pick the contracts LEAN would. Greek, implied
    volatility filters read model quotes through `quote_fn(symbol) -> OptionQuote`. Open interest and volume
    are not available: a range that excludes 0 raises NotSupportedByEngine instead of silently selecting
    nothing. Iterating yields OptionContract objects (also what contracts(func) passes to func)."""

    DEFAULT_AT_THE_MONEY_STRIKE_DISTANCE = 0.02
    DefaultAtTheMoneyStrikeDistance = DEFAULT_AT_THE_MONEY_STRIKE_DISTANCE

    def __init__(self, contracts=(), underlying=None, local_time=None, quote_fn=None, security_type=None,
                 underlying_scale_factor: float = 1.0):
        self._local_time = local_time
        self._quote_fn = quote_fn
        self._scale = float(underlying_scale_factor or 1.0)
        self._wrappers = {}
        syms = list(contracts)
        sym_type = Symbol
        for i, c in enumerate(syms):
            if type(c) is not sym_type:
                if isinstance(c, OptionContract):
                    self._wrappers[c.symbol] = c
                    syms[i] = c.symbol
                elif not isinstance(c, Symbol):
                    syms[i] = getattr(c, 'symbol', c)
        self._symbols = syms
        if security_type is None and syms:
            security_type = syms[0].security_type
        self._security_type = security_type
        sym0 = getattr(syms[0], 'underlying', None) if syms else None
        self._underlying = as_underlying(underlying, sym0, local_time)
        self._type = _BOTH
        self._types_applied = False
        self._unique_strikes = None
        self._last_exchange_date = _as_date(local_time) if local_time is not None else None

    # ---- data access ----
    def _wrap(self, s):
        w = self._wrappers.get(s)
        if w is None:
            w = self._wrappers[s] = OptionContract(s, self._local_time, self._underlying, quote_fn=self._quote_fn)
        return w

    @property
    def data(self) -> list:
        """The selected contracts as OptionContract objects."""
        return [self._wrap(s) for s in self._symbols]

    @property
    def symbols(self) -> list:
        return list(self._symbols)

    all_symbols = symbols

    def to_list(self) -> list:
        return list(self._symbols)

    @property
    def underlying(self):
        return self._underlying

    @property
    def local_time(self):
        return self._local_time

    @property
    def count(self) -> int:
        return len(self._symbols)

    def __len__(self):
        return len(self._symbols)

    def __iter__(self):
        return iter(self.data)

    def __repr__(self):
        return f"OptionFilterUniverse({len(self._symbols)} contracts, underlying={self._underlying})"

    def get_enumerator(self):
        return _Enumerator(list(self.data))

    GetEnumerator = get_enumerator

    def _set_symbols(self, symbols):
        """LEAN AllSymbols setter: keep the data of known contracts, create it for new ones."""
        self._symbols = [s if isinstance(s, Symbol) else self._lookup(s) for s in symbols]
        return self

    def _lookup(self, s):
        key = str(s).upper()
        for x in self._wrappers:
            if x.value == key:
                return x
        for x in self._symbols:
            if x.value == key:
                return x
        raise ValueError(f"OptionFilterUniverse.contracts(): unknown contract '{s}' (pass Symbols)")

    def _empty(self):
        self._symbols = []
        return self

    # ---- expiration type (standard / weekly) ----
    def apply_types_filter(self):
        if self._types_applied:
            return self
        if self._type != _BOTH:
            memo = {}
            keep = []
            for s in self._symbols:
                d = s.id.date
                std = memo.get(d)
                if std is None:
                    std = memo[d] = is_standard(s)
                if (self._type == _WEEKLY and not std) or (self._type == _STANDARD and std):
                    keep.append(s)
            self._symbols = keep
        self._types_applied = True
        return self

    def standards_only(self):
        if self._types_applied:
            raise RuntimeError("Type filters have already been applied, please call StandardsOnly() before "
                               "applying other filters such as FrontMonth() or BackMonths()")
        self._type = _STANDARD
        return self

    def include_weeklys(self):
        if self._types_applied:
            raise RuntimeError("Type filters have already been applied, please call IncludeWeeklys() before "
                               "applying other filters such as FrontMonth() or BackMonths()")
        self._type |= _WEEKLY
        return self

    def weeklys_only(self):
        self._type = _WEEKLY
        return self

    def only_apply_filter_at_market_open(self):
        return self

    # ---- expiration ----
    def front_month(self):
        self.apply_types_filter()
        if self._symbols:
            first = min(s.id.date for s in self._symbols)
            self._symbols = sorted((s for s in self._symbols if s.id.date == first), key=lambda s: s.id.date)
        return self

    def back_months(self):
        self.apply_types_filter()
        if self._symbols:
            first = min(s.id.date for s in self._symbols)
            self._symbols = sorted((s for s in self._symbols if s.id.date != first), key=lambda s: s.id.date)
        return self

    def back_month(self):
        return self.back_months().front_month()

    def farthest_expiration(self):
        self.apply_types_filter()
        if self._symbols:
            last = max(s.id.date for s in self._symbols)
            self._symbols = [s for s in self._symbols if s.id.date == last]
        return self

    def _reference_date(self) -> datetime:
        """LEAN AdjustExpirationReferenceDate: the universe date, moved to the next trading day if needed."""
        d = _as_date(self._local_time)
        if not cal.is_trading_day(d):
            d = cal.next_trading_day(d)
        return _dt(d)

    def expiration(self, min_expiry=None, max_expiry=None):
        """expiration(min_days, max_days) with ints or timedeltas, or expiration([dates])."""
        if max_expiry is None and min_expiry is not None and _is_iterable(min_expiry):
            days = {_as_date(x) for x in min_expiry}
            self._symbols = [s for s in self._symbols if s.id.date.date() in days]
            return self
        if self._local_time is None:
            return self
        ref = self._reference_date()
        lo = ref + _to_timedelta(min_expiry)
        hi = ref + _to_timedelta(max_expiry)
        keep = []
        for s in self._symbols:
            e = _dt(_lean_last_trading_date(s))
            if lo <= e <= hi:
                keep.append(s)
        self._symbols = keep
        return self

    def zero_dte(self):
        return self.expiration(0, 0)

    def expiring_after(self, d):
        dd = _as_date(d)
        self._symbols = [s for s in self._symbols if s.id.date.date() > dd]
        return self

    def expiring_before(self, d):
        dd = _as_date(d)
        self._symbols = [s for s in self._symbols if s.id.date.date() < dd]
        return self

    # ---- generic selection ----
    def contracts(self, contracts):
        """contracts(func) calls func(list of OptionContract) and keeps what it returns (contracts or
        Symbols); contracts(list) keeps the given contracts/Symbols (unknown Symbols are added, as LEAN)."""
        if callable(contracts) and not isinstance(contracts, (list, tuple, set)):
            result = contracts(self.data)
            items = list(result) if result is not None else []
        else:
            items = list(contracts)
        for x in items:
            if isinstance(x, OptionContract) and x.symbol not in self._wrappers:
                self._wrappers[x.symbol] = x
        return self._set_symbols(_to_symbol_list(items))

    def where(self, predicate):
        return self.contracts(lambda data: [x for x in data if predicate(x)])

    def select(self, map_func):
        return self.contracts(lambda data: [map_func(x) for x in data])

    def select_many(self, map_func):
        return self.contracts(lambda data: [y for x in data for y in map_func(x)])

    def where_contains(self, filter_list):
        wanted = {str(s).upper() for s in _to_symbol_list(filter_list)}
        self._symbols = [s for s in self._symbols if s.value in wanted]
        return self

    def _in_range(self, selector, mn, mx):
        mn, mx = float(mn), float(mx)
        keep = []
        for s in self._symbols:
            v = selector(self._wrap(s))
            if mn <= v <= mx:
                keep.append(s)
        self._symbols = keep
        return self

    def _not_available(self, name, mn, mx):
        if float(mn) <= 0.0 <= float(mx):
            return self   # every contract reports 0, which is inside the range
        raise not_supported(f"option {name} data (filter {name}({mn}, {mx}))",
                            f"Option {name} is not available from any free source; the model-priced chain "
                            f"reports 0 for every contract, so this filter cannot be applied.")

    def open_interest(self, min_value, max_value):
        self._validate_greek_filter('OpenInterest')
        return self._not_available('open interest', min_value, max_value)

    def oi(self, min_value, max_value):
        return self.open_interest(min_value, max_value)

    def volume(self, min_value, max_value):
        return self._not_available('volume', min_value, max_value)

    # ---- strikes ----
    def _underlying_price(self):
        return self._underlying.price if self._underlying is not None else None

    def strikes(self, min_strike, max_strike=None):
        """strikes(min, max): relative strike indexes around the underlying price (LEAN semantics);
        strikes([k1, k2, ...]): contracts with any of the given strikes."""
        if max_strike is None and _is_iterable(min_strike):
            ks = {_k(x) for x in min_strike}
            self._symbols = [s for s in self._symbols if _k(s.id.strike_price) in ks]
            return self
        if self._underlying is None:
            return self
        if self._unique_strikes is None:
            self._unique_strikes = sorted({s.id.strike_price for s in self._symbols})
        us = self._unique_strikes
        price = self._underlying_price() / self._scale
        index = bisect.bisect_left(us, price)
        exact = index < len(us) and us[index] == price
        if not exact and index == len(us):
            return self._empty()
        min_strike, max_strike = int(min_strike), int(max_strike)
        i_min = index + min_strike
        i_max = index + max_strike
        if not exact:
            if min_strike < 0 and max_strike > 0:
                i_max -= 1
            elif min_strike > 0:
                i_min -= 1
                i_max -= 1
        if i_min < 0:
            i_min = 0
        elif i_min >= len(us):
            return self._empty()
        if i_max < 0:
            return self._empty()
        if i_max >= len(us):
            i_max = len(us) - 1
        lo, hi = us[i_min], us[i_max]
        self._symbols = [s for s in self._symbols if lo <= s.id.strike_price <= hi]
        return self

    def strikes_above(self, price):
        p = float(price)
        self._symbols = [s for s in self._symbols if s.id.strike_price > p]
        return self

    def strikes_below(self, price):
        p = float(price)
        self._symbols = [s for s in self._symbols if s.id.strike_price < p]
        return self

    def calls_only(self):
        self._symbols = [s for s in self._symbols if s.id.option_right == _CALL]
        return self

    def puts_only(self):
        self._symbols = [s for s in self._symbols if s.id.option_right == _PUT]
        return self

    def out_of_the_money(self):
        if self._underlying is None:
            return self._empty()
        p = self._underlying_price() / self._scale
        self._symbols = [s for s in self._symbols
                         if (s.id.strike_price > p if s.id.option_right == _CALL else s.id.strike_price < p)]
        return self

    def otm(self):
        return self.out_of_the_money()

    def in_the_money(self):
        if self._underlying is None:
            return self._empty()
        p = self._underlying_price() / self._scale
        self._symbols = [s for s in self._symbols
                         if (s.id.strike_price < p if s.id.option_right == _CALL else s.id.strike_price > p)]
        return self

    def itm(self):
        return self.in_the_money()

    def at_the_money(self, max_strike_distance=None):
        if max_strike_distance is not None and max_strike_distance < 0:
            raise ValueError("AtTheMoney(): maxStrikeDistance must not be negative")
        if self._underlying is None:
            return self._empty()
        price = self._underlying_price() / self._scale
        if max_strike_distance is None:
            return self.strikes(self._bracketing_strikes(price))
        dist = float(max_strike_distance) / self._scale
        if dist == 0:
            return self.strikes([price])
        self._symbols = [s for s in self._symbols if abs(s.id.strike_price - price) <= dist]
        return self

    def atm(self, max_strike_distance=None):
        return self.at_the_money(max_strike_distance)

    def _bracketing_strikes(self, price):
        below = above = None
        for s in self._symbols:
            k = s.id.strike_price
            if k <= price and (below is None or k > below):
                below = k
            if k >= price and (above is None or k < above):
                above = k
        max_dist = price * type(self).DEFAULT_AT_THE_MONEY_STRIKE_DISTANCE
        out = []
        if below is not None and price - below <= max_dist:
            out.append(below)
        if above is not None and above != below and above - price <= max_dist:
            out.append(above)
        return out

    # ---- strategy helpers (LEAN private methods) ----
    def _contracts_for_expiry(self, symbols, min_days_till_expiry):
        if self._last_exchange_date is None:
            return []
        least = self._last_exchange_date + timedelta(days=int(min_days_till_expiry))
        cands = [s for s in symbols if _lean_last_trading_date(s) >= least]
        if not cands:
            return []
        first = min(s.id.date for s in cands)
        return sorted((s for s in cands if s.id.date == first),
                      key=lambda s: (s.id.strike_price, int(s.id.option_right), s.value))

    def _get_strike(self, symbols, strike_from_atm):
        target = self._underlying_price() + float(strike_from_atm)
        best = _MAX
        best_d = None
        for s in symbols:
            k = s.id.strike_price
            d = abs(target - k)
            if best_d is None or d < best_d or (d == best_d and k < best):
                best, best_d = k, d
        return best

    def _by_strike(self, symbols, strike):
        for s in symbols:
            if s.id.strike_price == strike:
                return s
        return None

    def _single_contract(self, right, min_days, strike_from_atm):
        if self._underlying is None:
            return self._empty()
        contracts = [s for s in self._contracts_for_expiry(self._symbols, min_days) if s.id.option_right == right]
        if not contracts:
            return self._empty()
        strike = self._get_strike(contracts, strike_from_atm)
        return self._set_symbols([self._by_strike(contracts, strike)])

    def naked_call(self, min_days_till_expiry: int = 30, strike_from_atm: float = 0):
        return self._single_contract(_CALL, min_days_till_expiry, strike_from_atm)

    def naked_put(self, min_days_till_expiry: int = 30, strike_from_atm: float = 0):
        return self._single_contract(_PUT, min_days_till_expiry, strike_from_atm)

    def _spread(self, right, min_days, higher_from_atm, lower_from_atm):
        if lower_from_atm is None:
            lower_from_atm = -higher_from_atm
        if higher_from_atm <= lower_from_atm:
            raise ValueError("Spread(): strike price arguments must be in descending order, "
                             "higherStrikeFromAtm, lowerStrikeFromAtm")
        if self._underlying is None:
            return self._empty()
        contracts = [s for s in self._contracts_for_expiry(self._symbols, min_days) if s.id.option_right == right]
        if not contracts:
            return self._empty()
        lower_strike = self._get_strike(contracts, lower_from_atm)
        lower = self._by_strike(contracts, lower_strike)
        higher_contracts = [s for s in contracts if s.id.strike_price > lower_strike]
        if not higher_contracts:
            return self._empty()
        higher = self._by_strike(higher_contracts, self._get_strike(higher_contracts, higher_from_atm))
        return self._set_symbols([lower, higher])

    def call_spread(self, min_days_till_expiry: int = 30, higher_strike_from_atm: float = 5,
                    lower_strike_from_atm: float = None):
        return self._spread(_CALL, min_days_till_expiry, higher_strike_from_atm, lower_strike_from_atm)

    def put_spread(self, min_days_till_expiry: int = 30, higher_strike_from_atm: float = 5,
                   lower_strike_from_atm: float = None):
        return self._spread(_PUT, min_days_till_expiry, higher_strike_from_atm, lower_strike_from_atm)

    def _calendar_spread(self, right, strike_from_atm, min_near, min_far, name='CalendarSpread'):
        if min_far <= min_near:
            raise ValueError(f"{name}(): expiry arguments must be in ascending order, "
                             "minNearDaysTillExpiry, minFarDaysTillExpiry")
        if min_near < 0:
            raise ValueError(f"{name}(): near expiry argument must be positive.")
        if self._underlying is None:
            return self._empty()
        strike = self._get_strike(self._symbols, strike_from_atm)
        contracts = [s for s in self._symbols if s.id.strike_price == strike and s.id.option_right == right]
        near = self._contracts_for_expiry(contracts, min_near)
        if not near:
            return self._empty()
        near = near[0]
        further = [s for s in contracts if s.id.date > near.id.date]
        far = self._contracts_for_expiry(further, min_far)
        if not far:
            return self._empty()
        return self._set_symbols([near, far[0]])

    def call_calendar_spread(self, strike_from_atm: float = 0, min_near_days_till_expiry: int = 30,
                             min_far_days_till_expiry: int = 60):
        return self._calendar_spread(_CALL, strike_from_atm, min_near_days_till_expiry, min_far_days_till_expiry)

    def put_calendar_spread(self, strike_from_atm: float = 0, min_near_days_till_expiry: int = 30,
                            min_far_days_till_expiry: int = 60):
        return self._calendar_spread(_PUT, strike_from_atm, min_near_days_till_expiry, min_far_days_till_expiry)

    def _call_put_spread(self, min_days, call_from_atm, put_from_atm, otm=False):
        if self._underlying is None:
            return self._empty()
        contracts = self._contracts_for_expiry(self._symbols, min_days)
        calls = [s for s in contracts if s.id.option_right == _CALL]
        puts = [s for s in contracts if s.id.option_right == _PUT]
        if otm:
            p = self._underlying_price()
            calls = [s for s in calls if s.id.strike_price > p]
            puts = [s for s in puts if s.id.strike_price < p]
        if not calls or not puts:
            return self._empty()
        call = self._by_strike(calls, self._get_strike(calls, call_from_atm))
        put = self._by_strike(puts, self._get_strike(puts, put_from_atm))
        return self._set_symbols([call, put])

    def strangle(self, min_days_till_expiry: int = 30, call_strike_from_atm: float = 5,
                 put_strike_from_atm: float = -5):
        if call_strike_from_atm <= 0:
            raise ValueError("Strangle(): callStrikeFromAtm must be positive")
        if put_strike_from_atm >= 0:
            raise ValueError("Strangle(): putStrikeFromAtm must be negative")
        return self._call_put_spread(min_days_till_expiry, call_strike_from_atm, put_strike_from_atm, True)

    def straddle(self, min_days_till_expiry: int = 30):
        return self._call_put_spread(min_days_till_expiry, 0, 0)

    def protective_collar(self, min_days_till_expiry: int = 30, call_strike_from_atm: float = 5,
                          put_strike_from_atm: float = -5):
        if call_strike_from_atm <= put_strike_from_atm:
            raise ValueError("ProtectiveCollar(): strike price arguments must be in descending order, "
                             "callStrikeFromAtm, putStrikeFromAtm")
        self._call_put_spread(min_days_till_expiry, call_strike_from_atm, put_strike_from_atm)
        calls = [s for s in self._symbols if s.id.option_right == _CALL]
        puts = [s for s in self._symbols if s.id.option_right == _PUT]
        if len(calls) != 1 or len(puts) != 1 or calls[0].id.strike_price <= puts[0].id.strike_price:
            return self._empty()
        return self

    def conversion(self, min_days_till_expiry: int = 30, strike_from_atm: float = 5):
        return self._call_put_spread(min_days_till_expiry, strike_from_atm, strike_from_atm)

    def _butterfly(self, right, min_days, strike_spread):
        if strike_spread <= 0:
            raise ValueError("ProtectiveCollar(): strikeSpread arguments must be positive")
        if self._underlying is None:
            return self._empty()
        contracts = [s for s in self._contracts_for_expiry(self._symbols, min_days) if s.id.option_right == right]
        if not contracts:
            return self._empty()
        price = self._underlying_price()
        atm = self._get_strike(contracts, 0)
        lower = self._get_strike([s for s in contracts if s.id.strike_price < price and s.id.strike_price < atm],
                                 -strike_spread)
        upper = atm * 2 - lower if lower != _MAX else -1.0
        expiry = contracts[0].id.date
        wanted = {_k(atm), _k(lower), _k(upper)}
        self._symbols = [s for s in self._symbols if s.id.date == expiry and s.id.option_right == right
                         and _k(s.id.strike_price) in wanted]
        if len(self._symbols) != 3:
            return self._empty()
        return self

    def call_butterfly(self, min_days_till_expiry: int = 30, strike_spread: float = 5):
        return self._butterfly(_CALL, min_days_till_expiry, strike_spread)

    def put_butterfly(self, min_days_till_expiry: int = 30, strike_spread: float = 5):
        return self._butterfly(_PUT, min_days_till_expiry, strike_spread)

    def iron_butterfly(self, min_days_till_expiry: int = 30, strike_spread: float = 5):
        if strike_spread <= 0:
            raise ValueError("IronButterfly(): strikeSpread arguments must be positive")
        if self._underlying is None:
            return self._empty()
        price = self._underlying_price()
        contracts = self._contracts_for_expiry(self._symbols, min_days_till_expiry)
        calls = [s for s in contracts if s.id.option_right == _CALL and s.id.strike_price > price]
        puts = [s for s in contracts if s.id.option_right == _PUT and s.id.strike_price < price]
        if not calls or not puts:
            return self._empty()
        atm = self._get_strike(contracts, 0)
        otm_call = self._get_strike([s for s in calls if s.id.strike_price > atm], strike_spread)
        otm_put = atm * 2 - otm_call if otm_call != _MAX else -1.0
        expiry = contracts[0].id.date
        self._symbols = [s for s in self._symbols if s.id.date == expiry and (
            _k(s.id.strike_price) == _k(atm)
            or (s.id.option_right == _CALL and _k(s.id.strike_price) == _k(otm_call))
            or (s.id.option_right == _PUT and _k(s.id.strike_price) == _k(otm_put)))]
        if len(self._symbols) != 4:
            return self._empty()
        return self

    def iron_condor(self, min_days_till_expiry: int = 30, near_strike_spread: float = 5,
                    far_strike_spread: float = 10):
        if near_strike_spread <= 0 or far_strike_spread <= 0:
            raise ValueError("IronCondor(): strike arguments must be positive, nearStrikeSpread, farStrikeSpread")
        if near_strike_spread >= far_strike_spread:
            raise ValueError("IronCondor(): strike arguments must be in ascending orders, "
                             "nearStrikeSpread, farStrikeSpread")
        if self._underlying is None:
            return self._empty()
        price = self._underlying_price()
        contracts = self._contracts_for_expiry(self._symbols, min_days_till_expiry)
        calls = [s for s in contracts if s.id.option_right == _CALL and s.id.strike_price > price]
        puts = [s for s in contracts if s.id.option_right == _PUT and s.id.strike_price < price]
        if not calls or not puts:
            return self._empty()
        near_call = self._get_strike(calls, near_strike_spread)
        near_put = self._get_strike(puts, -near_strike_spread)
        far_call = self._get_strike([s for s in calls if s.id.strike_price > near_call], far_strike_spread)
        far_put = near_put - far_call + near_call if far_call != _MAX else -1.0
        expiry = contracts[0].id.date
        nc, np_, fc, fp = _k(near_call), _k(near_put), _k(far_call), _k(far_put)
        self._symbols = [s for s in self._symbols if s.id.date == expiry and (
            (s.id.option_right == _CALL and _k(s.id.strike_price) in (nc, fc))
            or (s.id.option_right == _PUT and _k(s.id.strike_price) in (np_, fp)))]
        if len(self._symbols) != 4:
            return self._empty()
        return self

    def box_spread(self, min_days_till_expiry: int = 30, strike_spread: float = 5):
        if strike_spread <= 0:
            raise ValueError("BoxSpread(): strike arguments must be positive, strikeSpread")
        if self._underlying is None:
            return self._empty()
        price = self._underlying_price()
        contracts = self._contracts_for_expiry(self._symbols, min_days_till_expiry)
        if not contracts:
            return self._empty()
        higher = self._get_strike([s for s in contracts if s.id.strike_price > price], strike_spread)
        lower = self._get_strike([s for s in contracts if s.id.strike_price < higher and s.id.strike_price < price],
                                 -strike_spread)
        expiry = contracts[0].id.date
        hk, lk = _k(higher), _k(lower)
        self._symbols = [s for s in self._symbols
                         if _k(s.id.strike_price) in (hk, lk) and s.id.date == expiry]
        if len(self._symbols) != 4:
            return self._empty()
        return self

    def jelly_roll(self, strike_from_atm: float = 0, min_near_days_till_expiry: int = 30,
                   min_far_days_till_expiry: int = 60):
        if min_far_days_till_expiry <= min_near_days_till_expiry:
            raise ValueError("JellyRoll(): expiry arguments must be in ascending order, "
                             "minNearDaysTillExpiry, minFarDaysTillExpiry")
        if min_near_days_till_expiry < 0:
            raise ValueError("JellyRoll(): near expiry argument must be positive.")
        if self._underlying is None or not self._symbols:
            return self._empty()
        price = self._underlying_price()
        strike = min(self._symbols, key=lambda s: abs(price - s.id.strike_price + strike_from_atm)).id.strike_price
        calls = [s for s in self._symbols if s.id.strike_price == strike and s.id.option_right == _CALL]
        near = self._contracts_for_expiry(calls, min_near_days_till_expiry)
        if not near:
            return self._empty()
        near_expiry = near[0].id.date
        further = [s for s in calls if s.id.date > near_expiry]
        far = self._contracts_for_expiry(further, min_far_days_till_expiry)
        if not far:
            return self._empty()
        far_expiry = far[0].id.date
        self._symbols = [s for s in self._symbols if s.id.strike_price == strike
                         and (s.id.date == near_expiry or s.id.date == far_expiry)]
        if len(self._symbols) != 4:
            return self._empty()
        return self

    def _ladder(self, right, min_days, higher_from_atm, middle_from_atm, lower_from_atm):
        if (higher_from_atm <= lower_from_atm or higher_from_atm <= middle_from_atm
                or middle_from_atm <= lower_from_atm):
            raise ValueError("Ladder(): strike price arguments must be in descending order, "
                             "higherStrikeFromAtm, middleStrikeFromAtm, lowerStrikeFromAtm")
        if self._underlying is None:
            return self._empty()
        price = self._underlying_price()
        contracts = self._contracts_for_expiry([s for s in self._symbols if s.id.option_right == right], min_days)
        if not contracts:
            return self._empty()   # LEAN throws "Sequence contains no elements" here

        def closest(cands, off):
            return min(cands, key=lambda s: abs(price - s.id.strike_price + off)) if cands else None

        lower = closest(contracts, lower_from_atm)
        middle = closest([s for s in contracts if s.id.strike_price > lower.id.strike_price], middle_from_atm)
        if middle is None:
            return self._empty()
        higher = closest([s for s in contracts if s.id.strike_price > middle.id.strike_price], higher_from_atm)
        if higher is None:
            return self._empty()
        keep = {lower, middle, higher}
        self._symbols = [s for s in self._symbols if s in keep]
        return self

    def call_ladder(self, min_days_till_expiry: int, higher_strike_from_atm: float, middle_strike_from_atm: float,
                    lower_strike_from_atm: float):
        return self._ladder(_CALL, min_days_till_expiry, higher_strike_from_atm, middle_strike_from_atm,
                            lower_strike_from_atm)

    def put_ladder(self, min_days_till_expiry: int, higher_strike_from_atm: float, middle_strike_from_atm: float,
                   lower_strike_from_atm: float):
        return self._ladder(_PUT, min_days_till_expiry, higher_strike_from_atm, middle_strike_from_atm,
                            lower_strike_from_atm)

    # ---- greeks / implied volatility (model quotes through quote_fn) ----
    def _validate_greek_filter(self, name):
        if self._security_type == SecurityType.FUTURE_OPTION:
            raise RuntimeError(f"{name} filter is not supported for future options.")

    def _greek_range(self, name, selector, mn, mx):
        self._validate_greek_filter(name)
        if self._quote_fn is None and any(s not in self._wrappers or self._wrappers[s]._quote is None
                                          for s in self._symbols):
            raise not_supported(f"option {name} filters",
                                "No option pricing callback was supplied to the filter universe.")
        return self._in_range(selector, mn, mx)

    def delta(self, min_value, max_value):
        return self._greek_range('Delta', lambda c: c.greeks.delta, min_value, max_value)

    def gamma(self, min_value, max_value):
        return self._greek_range('Gamma', lambda c: c.greeks.gamma, min_value, max_value)

    def theta(self, min_value, max_value):
        return self._greek_range('Theta', lambda c: c.greeks.theta, min_value, max_value)

    def vega(self, min_value, max_value):
        return self._greek_range('Vega', lambda c: c.greeks.vega, min_value, max_value)

    def rho(self, min_value, max_value):
        return self._greek_range('Rho', lambda c: c.greeks.rho, min_value, max_value)

    def implied_volatility(self, min_value, max_value):
        return self._greek_range('ImpliedVolatility', lambda c: c.implied_volatility, min_value, max_value)

    d = delta
    g = gamma
    t = theta
    v = vega
    r = rho
    iv = implied_volatility


_alias(OptionFilterUniverse, [
    'standards_only', 'include_weeklys', 'weeklys_only', 'only_apply_filter_at_market_open', 'front_month',
    'back_months', 'back_month', 'farthest_expiration', 'expiration', 'expiring_after', 'expiring_before',
    'contracts', 'where', 'select', 'select_many', 'where_contains', 'open_interest', 'volume', 'strikes',
    'strikes_above', 'strikes_below', 'calls_only', 'puts_only', 'out_of_the_money', 'in_the_money',
    'at_the_money', 'naked_call', 'naked_put', 'call_spread', 'put_spread', 'call_calendar_spread',
    'put_calendar_spread', 'strangle', 'straddle', 'protective_collar', 'conversion', 'call_butterfly',
    'put_butterfly', 'iron_butterfly', 'iron_condor', 'box_spread', 'jelly_roll', 'call_ladder', 'put_ladder',
    'delta', 'gamma', 'theta', 'vega', 'rho', 'implied_volatility', 'underlying', 'local_time', 'count',
    'apply_types_filter'],
    {'OTM': 'otm', 'ITM': 'itm', 'ATM': 'atm', 'D': 'd', 'G': 'g', 'T': 't', 'V': 'v', 'R': 'r', 'IV': 'iv',
     'OI': 'oi', 'ZeroDte': 'zero_dte', 'AllSymbols': 'all_symbols'})


def set_filter_function(*args):
    """The filter LEAN's Option.SetFilter overloads build, as a callable(universe) -> universe:
        (func)                                    the user's filter function
        (min_strike, max_strike)                  ints: strikes(min, max)
        (min_expiry, max_expiry)                  timedeltas: expiration(min, max)
        (min_strike, max_strike, min_expiry, max_expiry)  strikes then expiration (ints = days or timedeltas)
    """
    if len(args) == 1 and callable(args[0]):
        return args[0]
    if len(args) == 2:
        a, b = args
        if isinstance(a, timedelta) or isinstance(b, timedelta):
            return lambda u: u.expiration(a, b)
        return lambda u: u.strikes(int(a), int(b))
    if len(args) == 4:
        mn_k, mx_k, mn_e, mx_e = args
        return lambda u: u.strikes(int(mn_k), int(mx_k)).expiration(mn_e, mx_e)
    raise TypeError(f"set_filter: unsupported arguments {args!r} (expected a function, (min_strike, max_strike), "
                    f"(min_expiry, max_expiry) or (min_strike, max_strike, min_expiry, max_expiry))")


def default_filter():
    """LEAN's default option filter: strikes(-1, 1).expiration(0, 35 days)."""
    return set_filter_function(-1, 1, timedelta(0), timedelta(days=35))


def apply_filter(filter_func, universe: OptionFilterUniverse) -> OptionFilterUniverse:
    """Run a user filter the way LEAN's Option.SetFilter does: a None result keeps the (in-place modified)
    universe, a universe result is used as is, a list of Symbols/contracts restricts the universe to them;
    then the expiration-type filter (standards/weeklys) is applied."""
    result = filter_func(universe) if filter_func is not None else universe
    if result is None:
        result = universe
    elif isinstance(result, OptionFilterUniverse):
        pass
    elif _is_iterable(result):
        result = universe.where_contains(list(result))
    else:
        raise TypeError(f"set_filter: result type {type(result).__name__} from filter function is not a valid "
                        f"argument, please return either a OptionFilterUniverse or a list of symbols")
    return result.apply_types_filter()
